1	package ociresources
2	
3	import (
4		"errors"
5		"log"
6		"net/url"
7		"strconv"
8		"strings"
9	
10		tea "charm.land/bubbletea/v2"
11		"charm.land/lipgloss/v2"
12	
13		"github.com/anthnel/devdesk/internal/imagesearch"
14		"github.com/anthnel/devdesk/internal/jobs"
15		"github.com/anthnel/devdesk/internal/oci"
16		"github.com/anthnel/devdesk/internal/ui/datatable"
17		"github.com/anthnel/devdesk/internal/ui/indicator"
18		"github.com/anthnel/devdesk/internal/ui/theme"
19	)
20	
21	// searchRow is one line of the level 1 table: an image, and the label of the
22	// registry that returned it.
23	type searchRow struct {
24		img   imagesearch.Image
25		label string
26		// ref is the full reference (host/repo), what the footer describes.
27		ref string
