135	// nothing, when the answer belongs to another lot. pendingSearches never goes
136	// below zero.
137	func (b *RegistryBrowser) AddImageResults(msg ImageSearchResultMsg) bool {
138		if msg.Gen != b.gen {
139			return false
140		}
141		if b.pendingSearches > 0 {
142			b.pendingSearches--
143		}
144		if msg.Err == nil {
145			for _, img := range msg.Images {
146				img.EntryKey = msg.EntryKey
147				b.images = append(b.images, img)
148			}
149		}
150		b.rebuildSearchTable()
151		return true
152	}
153	
154	// handleImagesKeyMsg handles the keys of the level 1 table. esc acts in
155	// order: the filter bar while it is open, then a confirmed query, then it
156	// cancels the lot and goes back to the form (which keeps the typed name and
157	// the selection). The lot's late answers are no longer wanted and are dropped
158	// (TestEscAtLevelOneCancelsTheLotAndIgnoresItsLateAnswers). enter does
159	// nothing: a row has no action yet.
160	func (b *RegistryBrowser) handleImagesKeyMsg(msg tea.KeyPressMsg) (*RegistryBrowser, tea.Cmd) {
161		if b.searchTable.InEditMode() {
162			return b, b.searchTable.Update(msg)
163		}
164		switch msg.String() {
165		case "esc":
166			if bar := b.searchTable.FilterBar(); bar.SearchQuery() != "" {
167				bar.ClearSearch()
168				b.searchTable.SetItems(b.searchTable.Items())
169				return b, nil
170			}
171			b.cancelInFlight()
172			b.gen = nextBrowserGen()
173			b.pendingSearches = 0
174			b.state = browserStateInput
175			b.searchTable.Blur()
176			b.updateFocus()
177			return b, nil
178		case "enter":
179			return b, nil
180		}
181		return b, b.searchTable.Update(msg)
182	}
183	
184	// handleImageSearchResult records one registry's answer; a stale one is ignored.
185	func (m Model) handleImageSearchResult(msg ImageSearchResultMsg) (tea.Model, tea.Cmd) {
186		if m.registryBrowser == nil || !m.registryBrowser.AddImageResults(msg) {
187			return m, nil
188		}
189		if msg.Err != nil {
190			alias := msg.EntryKey
191			if e := m.registryBrowser.entryFor(msg.EntryKey); e != nil {
192				alias = entryAlias(*e)
193			}
194			if errors.Is(msg.Err, imagesearch.ErrUnsupported) {
195				log.Printf("INFO [oci_resources] image search on %s: %s", alias, msg.Err)
196				return m, nil
197			}
198			log.Printf("ERROR [oci_resources] image search on %s: %s", alias, searchErrorCause(msg.Err))
199		}
200		return m, nil
201	}
202	
203	// searchErrorCause is the loggable text of a search error. A *url.Error holds
204	// the full request URL, which carries the text the user typed, so only its Op
205	// and Err are kept.
206	func searchErrorCause(err error) string {
207		var ue *url.Error
208		if errors.As(err, &ue) {
209			return jobs.SafeCause(errors.New(ue.Op + ": " + jobs.SafeCause(ue.Err)))
210		}
211		return jobs.SafeCause(err)
212	}
213	
214	// handleRegistryBrowserWarn shows the browser's warning in the footer.
215	func (m Model) handleRegistryBrowserWarn(msg RegistryBrowserWarnMsg) (tea.Model, tea.Cmd) {
216		return m, m.footer.Warn(strings.TrimSpace(msg.Text))
217	}
218

