11	// formAction is what a button of the browser form starts.
12	type formAction int
13	
14	const (
15		actionSearch   formAction = iota // IS-01 routing: short name + Searcher -> level 1, else tags
16		actionOpenTags                   // IS-11: always the tag lookup of the typed name
17	)
18	
19	// submit validates the form and starts action. An empty name starts nothing;
20	// no checked registry warns. actionSearch sends a name with no "/" to the image
21	// search when a Searcher is injected (level 1), anything else lists tags;
22	// actionOpenTags always lists the tags of the typed name.
23	func (b *RegistryBrowser) submit(action formAction) (*RegistryBrowser, tea.Cmd) {
24		repo := strings.TrimSpace(b.repoInput.Value())
25		if repo == "" {
26			return b, nil
27		}
28		var entries []browserRegistryEntry
29		for _, entry := range b.entries {
30			if b.selected(entry) {
31				entries = append(entries, entry)
32			}
33		}
34		if len(entries) == 0 {
35			return b, func() tea.Msg { return RegistryBrowserWarnMsg{Text: "No registry selected"} }
36		}
37		if action == actionSearch && b.searcher != nil && !strings.Contains(repo, "/") {
38			return b.startImageSearch(repo, entries)
39		}
40		return b.startTagLookup(repo, entries)
41	}
42	
43	// formButton is one button of the form: its label and what enter on it starts.
44	type formButton struct {
45		label  string
46		action formAction
47	}
48	
49	// formButtons is the single source of the form's buttons, read by the keyboard,
50	// the rendering and the header. Without a Searcher the form keeps its one
51	// Browse Tags button; with one, Search then Open Tags.
52	func (b *RegistryBrowser) formButtons() []formButton {
53		if b.searcher == nil {
54			return []formButton{{label: "Browse Tags", action: actionSearch}}
55		}
56		return []formButton{
57			{label: "Search", action: actionSearch},
58			{label: "Open Tags", action: actionOpenTags},
59		}
60	}
61	
62	// brFieldButton returns the form field index of the i-th button: right after
63	// the Repository field and the picker rows.
64	func (b *RegistryBrowser) brFieldButton(i int) int { return 1 + len(b.rows) + i }
65	
66	// brFieldLast returns the index of the last field, the last button.
67	func (b *RegistryBrowser) brFieldLast() int { return b.brFieldButton(len(b.formButtons()) - 1) }
68	
69	// focusedButton returns the button the focus is on, and false when it is on
70	// the Repository field or a checkbox.
71	func (b *RegistryBrowser) focusedButton() (formButton, bool) {
72		buttons := b.formButtons()
73		i := b.focusedField - b.brFieldButton(0)
74		if i < 0 || i >= len(buttons) {
75			return formButton{}, false
76		}
77		return buttons[i], true
78	}
79	
80	// renderFormButtons renders the buttons on one line.
81	func (b *RegistryBrowser) renderFormButtons() string {
82		var sb strings.Builder
83		sb.WriteString("  ")
84		for i, btn := range b.formButtons() {
85			if i > 0 {
86				sb.WriteString(theme.Bg("  "))
87			}
88			sb.WriteString(theme.RenderButton(btn.label, b.focusedField == b.brFieldButton(i), "primary"))
89		}
90		return sb.String()
91	}
92	
93	// FormEnter returns the label of the header's single enter entry and whether
94	// it is lit. The label follows the focus: "Search" on Repository and on the
95	// Search button, "Open tags" on the Open Tags button, "Browse tags" where no
96	// Searcher is wired. A checkbox only advances the focus, so enter is greyed
97	// there (it keeps the label of the Repository action). The keys never change.
98	func (b *RegistryBrowser) FormEnter() (label string, enabled bool) {
99		repoLabel := "Browse tags"
100		if b.searcher != nil {
101			repoLabel = "Search"
102		}
103		if b.focusedField == brFieldRepo {
104			return repoLabel, true
105		}
106		btn, ok := b.focusedButton()
107		if !ok {
108			return repoLabel, false
109		}
110		if btn.action == actionOpenTags {
111			return "Open tags", true
112		}
113		return repoLabel, true
114	}
