1	package ociresources
2	
3	import (
4		tea "charm.land/bubbletea/v2"
5	
6		"github.com/anthnel/devdesk/internal/config"
7		"github.com/anthnel/devdesk/internal/docker"
8		"github.com/anthnel/devdesk/internal/ui/keymap"
9	)
10	
11	// InEditMode returns true when a text input is active (blocks command mode).
12	func (b *RegistryBrowser) InEditMode() bool {
13		if b.state == browserStateInput && b.focusedField == brFieldRepo {
14			return true
15		}
16		if b.state == browserStateImages {
17			return b.searchTable.InEditMode()
18		}
19		return b.state == browserStateTags && b.filterActive
20	}
21	
22	// IsSearching returns true while registry tag queries are still in flight.
23	func (b *RegistryBrowser) IsSearching() bool {
24		return b.pendingSearches > 0
25	}
26	
27	// Update handles all messages for the browser.
28	func (b *RegistryBrowser) Update(msg tea.Msg) (*RegistryBrowser, tea.Cmd) {
29		switch msg := msg.(type) {
30		case tea.KeyPressMsg:
31			return b.handleKeyMsg(msg)
32		}
33		return b.delegateUpdate(msg)
34	}
35	
36	func (b *RegistryBrowser) delegateUpdate(msg tea.Msg) (*RegistryBrowser, tea.Cmd) {
37		if b.state == browserStateInput && b.focusedField == brFieldRepo {
38			var cmd tea.Cmd
39			b.repoInput, cmd = b.repoInput.Update(msg)
40			return b, cmd
41		}
42		if b.state == browserStateTags {
43			if b.filterActive {
44				var cmd tea.Cmd
45				b.filterInput, cmd = b.filterInput.Update(msg)
46				b.rebuildTagTable()
47				return b, cmd
48			}
49			return b, b.tagTable.Update(msg)
50		}
51		if b.state == browserStateImages {
52			return b, b.searchTable.Update(msg)
53		}
54		return b, nil
55	}
56	
57	func (b *RegistryBrowser) handleKeyMsg(msg tea.KeyPressMsg) (*RegistryBrowser, tea.Cmd) {
58		switch b.state {
59		case browserStateInput:
60			return b.handleInputKeyMsg(msg)
61		case browserStateTags:
62			return b.handleTagsKeyMsg(msg)
63		case browserStateImages:
64			return b.handleImagesKeyMsg(msg)
65		}
66		return b, nil
67	}
68	
69	func (b *RegistryBrowser) handleInputKeyMsg(msg tea.KeyPressMsg) (*RegistryBrowser, tea.Cmd) {
70		switch msg.String() {
71		case "esc":
72			return b, func() tea.Msg { return RegistryBrowserCloseMsg{} }
73		case "down":
74			b.focusedField = min(b.focusedField+1, b.brFieldLast())
75			b.updateFocus()
76			return b, nil
77		case "up":
78			b.focusedField = max(b.focusedField-1, brFieldRepo)
79			b.updateFocus()
80			return b, nil
81		case keymap.Space:
82			if b.focusedField >= 1 && b.focusedField <= len(b.rows) {
83				row := b.rows[b.focusedField-1]
84				if row.groupSlug != "" {
85					b.toggleGroup(row.groupSlug)
86					return b, nil
87				}
88				key := b.entries[row.entry].key
89				b.selectedRegs[key] = !b.selectedRegs[key]
90				return b, nil
91			}
92		case "enter":
93			if b.focusedField == brFieldRepo {
94				return b.submit(actionSearch)
95			}
96			if btn, ok := b.focusedButton(); ok {
97				return b.submit(btn.action)
98			}
99			b.focusedField = min(b.focusedField+1, b.brFieldLast())
100			b.updateFocus()
101			return b, nil
102		}
103		return b.delegateUpdate(msg)
104	}
105	
106	// credsFor returns the credentials to search entry with, and nothing at all
107	// when the registry — or the group it belongs to — is marked anonymous (D12).
108	// Docker keys credentials by host, so a Nexus instance with one repository
109	// logged into would otherwise send that login to every repository it serves.
110	func (b *RegistryBrowser) credsFor(entry browserRegistryEntry) (string, string) {
111		if !config.UsesCredentials(entry.authMode) {
112			return "", ""
113		}
114		// Credentials come from the parent registry, or the entry itself for a
115		// registry that is not a group member.
116		credURL := entry.URL
117		if entry.parentURL != "" {
118			credURL = entry.parentURL
119		}
120		var username string
121		for _, reg := range b.registries {
122			if reg.URL == credURL {
123				username = reg.Username
124				break
125			}
126		}
127		storedUser, storedPass, _ := docker.GetStoredCreds(credURL)
128		if username == "" {
129			username = storedUser
130		}
131		return username, storedPass
132	}
133	
134	// entryAlias is the label a result of entry carries: the alias, behind its
135	// group's when it is a member.
136	func entryAlias(entry browserRegistryEntry) string {
137		if entry.ParentAlias != "" {
138			return entry.ParentAlias + "/" + entry.Alias
139		}
140		return entry.Alias
141	}
142	
143	// startTagLookup lists the tags of repo on every entry.
144	func (b *RegistryBrowser) startTagLookup(repo string, entries []browserRegistryEntry) (*RegistryBrowser, tea.Cmd) {
145		// Gather the requests first, then begin the lot: nothing is cancelled
146		// unless a request really starts.
147		type request struct {
148			entry                         browserRegistryEntry
149			alias, apiURL, repo, user, pw string
150		}
151		reqs := make([]request, 0, len(entries))
152		for _, entry := range entries {
153			username, storedPass := b.credsFor(entry)
154			// The prefix is applied here and nowhere else: it is then already part
155			// of MultiRegistryTag.Repo, so multiImageName and registryAPIURL need to
156			// know nothing about it. Teaching both would be two places free to
157			// drift, which is the disagreement D39 already is (§3.18).
158			normalizedRepo := joinRepoPrefix(entry.repoPrefix, normalizeRepoForRegistry(entry.URL, repo))
159			reqs = append(reqs, request{entry, entryAlias(entry), registryAPIURL(entry.URL), normalizedRepo, username, storedPass})
160		}
161	
162		ctx := b.beginRequests()
163		b.tags = nil
164		b.registryFilter = resultFilter{}
165		b.filterInput.SetValue("")
166		b.filterActive = false
167		// A new search starts from the default order, not wherever the last one's
168		// `.` presses left the table.
169		b.tagTable.SetSort(tagColumnTag, false)
170	
171		cmds := make([]tea.Cmd, 0, len(reqs))
172		for _, r := range reqs {
173			b.pendingSearches++
174			cmds = append(cmds, searchRegistryTagsCmd(ctx, b.gen, r.entry.key, r.entry.URL, r.alias, r.apiURL, r.repo, r.user, r.pw))
175		}
176	
177		b.state = browserStateTags
178		b.tagTable.Focus()
179		b.rebuildTagTable()
180		return b, tea.Batch(cmds...)
181	}
182	
183	func (b *RegistryBrowser) handleTagsKeyMsg(msg tea.KeyPressMsg) (*RegistryBrowser, tea.Cmd) {
184		if b.filterActive {
185			switch msg.String() {
186			case "esc", "enter":
187				b.filterActive = false
188				b.filterInput.Blur()
189				b.rebuildTagTable()
190				b.resizeTables()
191				return b, nil
192			}
193			return b.delegateUpdate(msg)
194		}
195	
196		switch msg.String() {
197		case "esc":
198			b.state = browserStateInput
199			b.tagTable.Blur()
200			b.updateFocus()
201			return b, nil
202		case "/":
203			b.filterActive = true
204			b.filterInput.Focus()
205			b.resizeTables()
206			return b, nil
207		case "r":
208			b.cycleRegistryFilter()
209			return b, nil
210		case "enter":
211			return b.openTagScanDetails()
212		case keymap.Get:
213			return b.pullSelectedTag()
214		case keymap.Scan:
215			return b.requestDirectScan()
216		}
217		// Navigation and `.` are the table's. `/` never reaches it: the browser's
218		// own filter took the key two cases above, and the table declares no
219		// searchable column, so it would decline it anyway.
220		return b, b.tagTable.Update(msg)
221	}
