77	// handleRegistryPullRequested admits a browser pull as a job and puts the user
78	// where they can watch it: the Images tab, browser closed (§3.60).
79	//
80	// A pull is asked for from the browser and answered in the Images list, and
81	// leaving the user on the browser's own spinner meant the one screen that could
82	// not show either the progress or the result. The switch happens here, once, on
83	// the keypress that asked for it — it is not a work message dragging the screen
84	// around behind the user's back, which is what D67 forbids.
85	func (m Model) handleRegistryPullRequested(msg RegistryPullRequestedMsg) (tea.Model, tea.Cmd) {
86		if m.pullingImage(msg.ImageName) {
87			return m, m.footer.Warn("Pull already in progress")
88		}
89		start := jobs.Start(m.pullRun(msg.ImageName), pullOneImageCmd(msg.ImageName, m.pullDeps()))
90	
91		// closeMultiRegistryBrowser carries the deselection the next visit reopens
92		// on, so the browser is closed through it rather than by hand.
93		closed, closeCmd := m.closeMultiRegistryBrowser()
94		next, ok := closed.(Model)
95		if !ok {
96			return closed, tea.Batch(closeCmd, start)
97		}
98		next.activeTab = tabImages
99		next.updateImageTable()
100		return next, tea.Batch(closeCmd, start)
101	}
102	
103	// handleRegistryPullComplete processes the result of a pull.
104	//
105	// It does not depend on the browser any more: the pull outlives it now that
106	// asking for one closes it, and a completion that returned early on a nil
107	// browser would skip the refresh that makes the pulled image appear.
108	func (m Model) handleRegistryPullComplete(msg RegistryPullCompleteMsg) (tea.Model, tea.Cmd) {
109		if msg.Replaces != "" {
110			return m.handleImageUpdated(msg)
111		}
112		if isBlocked(msg.Err) {
113			log.Printf("ERROR [oci_resources] pull %s refused: %v", msg.ImageName, msg.Err)
114			return m, m.footer.Error("Pull of " + msg.ImageName + " refused: " + msg.Err.Error())
115		}
116		if msg.Err != nil {
117			log.Printf("ERROR [oci_resources] pull %s: %v", msg.ImageName, msg.Err)
118			return m, m.footer.Error("Pull failed — check logs")
119		}
120		if msg.Check.Decision == trust.Warn {
121			return m, tea.Batch(fetchImages(), m.footer.Warn("Pulled "+msg.ImageName+" — "+msg.Check.Reason()))
122		}
123		return m, tea.Batch(fetchImages(), m.footer.Info("Image pulled: "+msg.ImageName))
124	}
