126	// handleRegistryTagDirectScan starts a direct remote Trivy scan without pulling the image.
127	func (m Model) handleRegistryTagDirectScan(msg RegistryTagDirectScanMsg) (tea.Model, tea.Cmd) {
128		if m.scanningImage(msg.ImageName) {
129			return m, m.footer.Warn("Scan already in progress")
