154	// browser any more: the browser reads the cache when it opens, so a refresh is
155	// something the Registries tab does and the Members column reports.
156	func (m Model) handleRegistryGroupDetected(msg RegistryGroupDetectedMsg) (tea.Model, tea.Cmd) {
157		delete(m.refreshingGroups, msg.Slug)
158	
159		if msg.Err != nil {
160			log.Printf("INFO [oci_resources] group detection failed for %s: %v", msg.RegistryURL, msg.Err)
161			// The cache keeps what was last known rather than being emptied by an
162			// unreachable manager, so the column keeps showing it — stale, and
163			// visibly so.
164			m.updateRegistryTable()
165			return m, m.footer.Error("Group refresh failed — check logs")
166		}
167		if msg.Slug != "" {
168			m.groupCache[msg.Slug] = cache.RegistryGroupEntry{
169				Members:      toCachedMembers(msg.Members),
170				DiscoveredAt: time.Now(),
