178	// the table hold.
179	func toCachedMembers(members []registrymgr.GroupMember) []cache.RegistryGroupMember {
180		out := make([]cache.RegistryGroupMember, 0, len(members))
181		for _, m := range members {
182			out = append(out, cache.RegistryGroupMember{Alias: m.Alias, URL: m.URL, RepoPrefix: m.RepoPrefix})
183		}
