153	// formStatus is the status while a form or the browser has the viewport. The
154	// tables behind them are not on screen, so their loads say nothing here; the
155	// browser's own search does.
156	func (m Model) formStatus() sharedcomponents.Status {
157		if m.registryBrowser != nil {
158			if text, ok := m.registryBrowser.LoadingLabel(); ok {
159				return sharedcomponents.Status{Text: text, Activity: true}
160			}
161			// Past the search, the footer says what the tag under the cursor is doing.
162			if row, ok := m.registryBrowser.tagTable.Selected(); ok && m.registryBrowser.state == browserStateTags {
163				return sharedcomponents.Status{Detail: row.Activity.Detail}
164			}
165			// Level 1, search done: the footer describes the selected row.
166			if row, ok := m.registryBrowser.searchTable.Selected(); ok && m.registryBrowser.state == browserStateImages {
167				detail := sharedcomponents.RowDetail{Lead: "Image ", Target: row.ref}
168				// A registry the list no longer knows leaves no label: no dangling " on".
169				if row.label != "" {
170					detail.Tail = " on " + row.label
171				}
172				return sharedcomponents.Status{Detail: detail}
173			}
174		}
175		if m.networkInspectForm != nil && m.networkInspectForm.loading {
176			return sharedcomponents.Status{Text: "Loading containers...", Activity: true}
177		}
178		if m.launchForm != nil {
179			if st := m.launchForm.ValidationStatus(); st.Text != "" {
180				return st
181			}
182		}
183		return sharedcomponents.Status{}
184	}
