// formStatus is the status while a form or the browser has the viewport. The
// tables behind them are not on screen, so their loads say nothing here; the
// browser's own search does.
func (m Model) formStatus() sharedcomponents.Status {
	if m.registryBrowser != nil {
		if text, ok := m.registryBrowser.LoadingLabel(); ok {
			return sharedcomponents.Status{Text: text, Activity: true}
		}
		// Past the search, the footer says what the tag under the cursor is doing.
		if row, ok := m.registryBrowser.tagTable.Selected(); ok && m.registryBrowser.state == browserStateTags {
			return sharedcomponents.Status{Detail: row.Activity.Detail}
		}
		// Level 1, search done: the footer describes the selected row.
		if row, ok := m.registryBrowser.searchTable.Selected(); ok && m.registryBrowser.state == browserStateImages {
			detail := sharedcomponents.RowDetail{Lead: "Image ", Target: row.ref}
			// A registry the list no longer knows leaves no label: no dangling " on".
			if row.label != "" {
				detail.Tail = " on " + row.label
			}
			return sharedcomponents.Status{Detail: detail}
		}
	}
	if m.networkInspectForm != nil && m.networkInspectForm.loading {
		return sharedcomponents.Status{Text: "Loading containers...", Activity: true}
	}
	if m.launchForm != nil {
		if st := m.launchForm.ValidationStatus(); st.Text != "" {
			return st
		}
	}
	return sharedcomponents.Status{}
}

// loadingLabel names what the active tab is fetching, or reports that it is
// settled. Only the tab on screen answers: a volumes load says nothing while
// the Images tab is showing.
func (m Model) loadingLabel() (string, bool) {
	switch m.activeTab {
	case tabImages:
		return "Loading images...", m.loading && len(m.images) == 0
	case tabNetworks:
		return "Loading networks...", m.loadingNets && len(m.networkTable.Items()) == 0
	case tabVolumes:
		return "Loading volumes...", m.loadingVols && len(m.volumeTable.Items()) == 0
	}
	return "", false
}

// footerLoading reports whether the footer shows a load of this view's own,
// whichever face it renders: the active tab's (table empty only), the
// browser's search, or the network inspection. WantsBlink reads it, in the
// same priority order as formStatus.
func (m Model) footerLoading() bool {
	if !m.formMode() {
