186	// loadingLabel names what the active tab is fetching, or reports that it is
187	// settled. Only the tab on screen answers: a volumes load says nothing while
188	// the Images tab is showing.
189	func (m Model) loadingLabel() (string, bool) {
190		switch m.activeTab {
191		case tabImages:
192			return "Loading images...", m.loading && len(m.images) == 0
193		case tabNetworks:
194			return "Loading networks...", m.loadingNets && len(m.networkTable.Items()) == 0
195		case tabVolumes:
196			return "Loading volumes...", m.loadingVols && len(m.volumeTable.Items()) == 0
197		}
