201	// footerLoading reports whether the footer shows a load of this view's own,
202	// whichever face it renders: the active tab's (table empty only), the
203	// browser's search, or the network inspection. WantsBlink reads it, in the
204	// same priority order as formStatus.
205	func (m Model) footerLoading() bool {
206		if !m.formMode() {
207			_, ok := m.loadingLabel()
208			return ok
209		}
210		if m.registryBrowser != nil {
