219	// the Registries tab has entered a group (Rules 111, 123). Breadcrumb mode: it
220	// is not navigable, the level you are on is highlighted and the one above is
221	// dimmed. Empty at the top level, where there is no trail to show.
222	func (m Model) renderRegistryBreadcrumb(width int) string {
223		group := m.drilledGroup()
