245	// GetTitle returns the view title
246	func (m Model) GetTitle() string {
247		base := theme.ContainerEngineIcon(engine.Current().Name) + " OCI Resources"
248		if m.registryBrowser != nil {
249			title := base + " " + theme.IconChevronRight + " Registry Browser"
250			if m.registryBrowser.state != browserStateInput && m.registryBrowser.repoInput.Value() != "" {
251				title += " " + theme.IconChevronRight + " " + m.registryBrowser.repoInput.Value()
252			}
253			if !m.registryBrowser.registryFilter.isEmpty() {
254				title += " [" + m.registryBrowser.registryFilterLabel() + "]"
255			}
256			return title
257		}
258		if m.launchForm != nil {
259			return base + " " + theme.IconChevronRight + " Launch Container"
260		}
261		if m.resourceForm != nil {
262			return base + " " + theme.IconChevronRight + " " + m.resourceForm.GetTitle()
263		}
