278	// GetHeaderInfo returns the key-value info for the header
279	func (m Model) GetHeaderInfo(_ string) []shortcut.HeaderInfo {
280		if m.registryBrowser != nil && m.registryBrowser.state == browserStateTags {
281			return []shortcut.HeaderInfo{
282				{Key: "Tags", Value: fmt.Sprintf("%d", len(m.registryBrowser.tagTable.Items())), Style: theme.HeaderValueStyle},
283			}
284		}
285		if m.registryBrowser != nil && m.registryBrowser.state == browserStateImages {
286			return []shortcut.HeaderInfo{
287				{Key: "Images", Value: fmt.Sprintf("%d", len(m.registryBrowser.searchTable.Visible())), Style: theme.HeaderValueStyle},
288			}
289		}
290		if m.networkInspectForm != nil {
291			return []shortcut.HeaderInfo{
292				{Key: "Containers", Value: fmt.Sprintf("%d", len(m.networkInspectForm.containers)), Style: theme.HeaderValueStyle},
293			}
294		}
295		switch m.activeTab {
296		case tabNetworks:
297			return []shortcut.HeaderInfo{
298				{Key: "Networks", Value: fmt.Sprintf("%d", len(m.networkTable.Items())), Style: theme.HeaderValueStyle},
299			}
300		case tabVolumes:
301			return []shortcut.HeaderInfo{
302				{Key: "Volumes", Value: fmt.Sprintf("%d", len(m.volumeTable.Items())), Style: theme.HeaderValueStyle},
303			}
304		case tabRegistries:
305			return []shortcut.HeaderInfo{
306				{Key: "Registries", Value: fmt.Sprintf("%d", len(m.registries)), Style: theme.HeaderValueStyle},
307			}
308		default:
309			visible := m.imageTable.Visible()
310			total := len(visible)
311			var totalDisk int64
312			for _, row := range visible {
313				totalDisk += row.Image.UniqueSize
314			}
315			infos := []shortcut.HeaderInfo{
316				{Key: "Images", Value: fmt.Sprintf("%d", total), Style: theme.HeaderValueStyle},
317				{Key: "Disk Usage", Value: formatBytes(totalDisk), Style: theme.HeaderValueStyle},
318			}
319			unscanned := m.unscannedCount()
320			if unscanned > 0 {
321				infos = append(infos, shortcut.HeaderInfo{
322					Key:   "Unscanned",
323					Value: fmt.Sprintf("%d", unscanned),
324					Style: lipgloss.NewStyle().Foreground(theme.ColorHighlight).Background(theme.ColorBackground),
325				})
326			}
327			if sig, ok := m.signatureHeader(); ok {
328				infos = append(infos, sig)
329			}
330			return infos
331		}
332	}
333	
334	// GetShortcuts returns the keyboard shortcuts for the header (Rule 130: dynamic shortcuts)
335	func (m Model) GetShortcuts() shortcut.Shortcuts {
336		if m.registryBrowser != nil {
337			switch m.registryBrowser.state {
338			case browserStateTags:
339				if m.registryBrowser.filterActive {
340					return []shortcut.Shortcut{
341						{Key: "enter/esc", Description: "Close filter"},
342					}
343				}
344				// enter is greyed on a tag nothing has scanned yet, rather than
345				// appearing and disappearing as the cursor runs down the list
346				// (Rule 130).
347				return []shortcut.Shortcut{
348					{Key: "enter", Description: "View CVE details",
349						Disabled: !m.registryBrowser.HasSelectedTagScanResults()},
350					{Key: keymap.Scan, Description: "Scan image"},
351					{Key: keymap.Get, Description: "Pull image"},
352					{Key: "r", Description: "Filter registry"},
353					{Key: "/", Description: "Filter"},
354					{Key: ".", Description: "Sort"},
355					{Key: "esc", Description: "Go back"},
356				}
357			case browserStateImages:
358				// No enter (a row has no action yet), no sort, no drill-down: the
359				// set of keys never depends on the rows (Rule 130).
360				if m.registryBrowser.searchTable.InEditMode() {
361					return []shortcut.Shortcut{
362						{Key: "enter/esc", Description: "Close filter"},
363					}
364				}
365				// esc clears a confirmed query before it goes back: same key,
366				// the label follows what it will do.
367				escLabel := "Go back"
368				if m.registryBrowser.searchTable.FilterBar().SearchQuery() != "" {
369					escLabel = "Clear filter"
370				}
371				return []shortcut.Shortcut{
372					{Key: "/", Description: "Filter"},
373					{Key: "esc", Description: escLabel},
374				}
375			default: // browserStateInput
376				// One enter entry whose label follows the focus; it is greyed on a
377				// checkbox, where enter only advances. A control, not an action:
378				// greying is the whole of it, and a footer line on every stray enter
379				// in a form would be noise.
380				enterLabel, enterLit := m.registryBrowser.FormEnter()
381				return []shortcut.Shortcut{
382					{Key: "enter", Description: enterLabel, Disabled: !enterLit},
383					{Key: "esc", Description: "Close browser"},
384				}
385			}
386		}
387		if m.launchForm != nil {
388			lf := m.launchForm
389			isCheckbox := lf.isPortField(lf.focusedField) ||
390				lf.focusedField == lf.fieldOptionRemove() ||
391				lf.focusedField == lf.fieldOptionDetach() ||
392				lf.focusedField == lf.fieldOptionInteractive()
393			// The three controls a field can take, greyed rather than swapped: the
394			// column changed shape on every ↑↓, in a form where the cursor moves
395			// constantly (Rule 130).
396			return []shortcut.Shortcut{
397				{Key: "space", Description: "Toggle", Disabled: !isCheckbox},
398				{Key: "←→", Description: "Cycle network", Disabled: lf.focusedField != lf.fieldNetwork()},
399				{Key: "enter", Description: "Launch", Disabled: lf.focusedField != lf.fieldSubmit()},

